import{_ as o,l as s,o as e,c as i,v as r,p as l,x as n,d as h,i as u,S as d}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"特征：滞后、截面 rank","description":"","frontmatter":{"title":"特征：滞后、截面 rank","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cs-rank-features.md","filePath":"quant/cs-rank-features.md","lastUpdated":1789023840000}'),p={name:"quant/cs-rank-features.md"};function k(E,a,c,m,A,_){const t=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="特征-滞后、截面-rank" tabindex="-1">特征：滞后、截面 rank <a class="header-anchor" href="#特征-滞后、截面-rank" aria-label="Permalink to &quot;特征：滞后、截面 rank&quot;">​</a></h1><div class="epigraph"><p>会计变量在进入横截面之前必须滞后到投资人可获得；用财政年度结束日的账面去解释当年收益，测到的不是价值溢价，是前视。</p><footer>—— 据 Fama and French 对账面市值比构造与 Compustat 可获得性滞后的标准处理</footer></div><p>表格特征在进入模型之前有两步几乎决定结论：什么时候能用（滞后），以及在谁之间比较（截面变换）。Fama 与 French 把账面股权放到至少六个月后的组合形成日，避免用尚未公布的年报。Hou、Xue 与 Zhang（2020）在复制异常时强调 NYSE 断点与滞后，许多「显著」在这一手续下消失。Green、Hand 与 Zhang（2017）同时放入几十个特征，问的是增量信息而不是单个 t。Kelly、Pruitt 与 Su（2019）的 IPCA 把特征当作载荷的函数；Kozak、Nagel 与 Santosh（2020）在特征空间里收缩。截面 rank 或 z-score 是 Barra 与多空排序的共同语言，见<a href="/quant/long-short-sort">单因子排序</a>。本篇把滞后与 rank 写成特征工程的最小充分统计：不做这两步，<a href="/quant/gbdt-alpha">GBDT</a> 会把规模、单位和前视当成「非线性」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原始描述子的量纲不可比：B/M 是比率，过去收益是小数，成交额是货币，分析师人数是计数。树模型虽然对单调变换不敏感，但对<strong>离群点与缺失</strong>敏感，且不同特征的分裂增益会偏向高方差、厚尾的列。线性模型则直接被量纲支配。截面 rank 把每个 \\(t\\) 上的 \\(x_{i,t}\\) 变成 \\(\\{1,\\ldots,N_t\\}\\) 上的次序或分位，去掉水平漂移（通胀、指数点位）并压住极端值。问题是 rank 的总体是谁：全体股票、NYSE、某个流动性宇宙。总体一变，同一家公司的分位可以穿过整个因子，这与 FF 用 NYSE 断点是同一道理。</p><p>滞后是信息集。财报、分析师、宏观、另类数据各有可获得时钟。用 \\(t\\) 月的应计去预测 \\(t\\) 月收益，若应计要到季报发布才知，就是未来函数。即使「季度已经结束」，未公布仍不可交易。Fama–French 的六个月是保守规则；更精细的做法是用实际公告日（Compustat RDQ）逐公司滞后，但缺失与修正会引入选择偏差。另类数据的 vintage 见<a href="/quant/satellite-geo">卫星</a>与<a href="/quant/card-spending">卡消费</a>：供应商回填历史等同于把未来的商户分类用到过去。</p><h3 id="rank-不是唯一的截面变换-但往往是最可审计的" tabindex="-1">Rank 不是唯一的截面变换，但往往是最可审计的 <a class="header-anchor" href="#rank-不是唯一的截面变换-但往往是最可审计的" aria-label="Permalink to &quot;Rank 不是唯一的截面变换，但往往是最可审计的&quot;">​</a></h3><p>截面 z-score（减中位数、除以中位数绝对偏差）保留一点形状，仍对极端值敏感。行业内 rank 先去掉<a href="/quant/industry-neutral">行业</a>水平，相当于把特征变成行业相对。市值分层后的 rank 避免小盘包办两端。Freyberger、Neuhierl 与 Weber（2020）用自适应分组看特征的非线性；那是估计问题。工程上应先交付「日期 \\(t\\)、宇宙 \\(U_t\\)、行业内分位」这一可复现对象，再谈自适应。缺失值：不参与 rank 的股票应保持缺失，而不是填 0.5，否则模型把「没数据」当成中性，对分析师覆盖稀疏的名字系统性误分类。</p><p><span class="marginnote">对时间序列做 rank（一只股票自己过去一年的分位）测的是自身极端程度，不是横截面相对价值。两种 rank 可以同时用，但必须命名：cs_rank 与 ts_rank 混用是常见的研究不可复现来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>滞后表。</strong> 为每一列写：源、频率、法定或供应商延迟、保守缓冲、修订政策。价格与成交来自市场，滞后通常是「只用 \\(t\\) 日收盘及以前」；会计用公告日或 FF 六个月；分析师用 IBES 统计日；宏观用实时数据库 vintage。特征矩阵的每一行对应一个<strong>可交易日期</strong>，该行所有列必须属于该日信息集。Gu–Kelly–Xiu 的特征清单长，正是因为每列都经过这一手续；复制他们的结果却用点对点对齐的 Compustat 当年值，不是复制。</p><p><strong>截面变换。</strong> 每个 \\(t\\) 在宇宙 \\(U_t\\) 上计算分位 \\(q_{i,t}=F_{t,U}(x_{i,t})\\)。\\(U_t\\) 应与组合可投资集合一致：有价格、有最小成交额、未停牌。Winsorize 再 z-score 是线性模型的传统；树可以用分位，减少一次超参。行业内分位：先按分类映射，行业内不足够多名字则退回全局分位并做标记。双重 rank（先行业再全局）要预先指定顺序，顺序会改变正交含义，见<a href="/quant/factor-orthogonal">因子正交</a>。</p><p><strong>与排序实验对齐。</strong> 若最终交易是十分位多空，训练标签与特征都应在同一宇宙、同一断点哲学下生成，否则模型在学一套分布、组合在另一套上成交。Hou–Xue–Zhang 复制失败常常来自断点与滞后，而不是来自机器学习。</p><h3 id="滞后不足与滞后过度" tabindex="-1">滞后不足与滞后过度 <a class="header-anchor" href="#滞后不足与滞后过度" aria-label="Permalink to &quot;滞后不足与滞后过度&quot;">​</a></h3><p>滞后不足：前视，样本内完美，实盘崩塌。滞后过度：用一年前的会计去预测下周微观结构收益，IC 被衰减掉，模型只能去拟合噪声。会计特征配月频标签、微观结构特征配短 \\(h\\)，见<a href="/quant/label-horizon-overlap">标签与重叠</a>。把全部特征强行滞后到最慢的那一列（例如都等年报），是在用会计日历阉割高频信息；正确做法是<strong>按列滞后</strong>，而不是按行统一延迟。</p><p><span class="marginnote">拆股、分红调整会改变过去收益与价格特征。应用同一套调整规则，并在除权日检查 rank 是否跳变。跳变若来自调整错误，会成为树的虚假分裂点。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>截面 rank 使特征对共同水平冲击（市场上涨、通胀）近似不变，于是线性模型的系数更接近「相对高低」而不是「绝对大小」。这也去掉一部分时变波动：牛市里原始动量绝对值变大，分位仍然在 \\(0\\) 与 \\(1\\) 之间。代价是丢掉水平里可能存在的宏观信息——若你确实要用估值的绝对水平做择时，应另建时间序列特征，不要让截面 rank 偷偷承担择时，见<a href="/quant/ic-ir-timing">IC 与择时</a>。</p><p>Rank 的非线性：两端的经济含义往往更强（极端价值、极端动量），中间接近噪声。树会自动在分位两端多分裂；线性模型需要预先加平方项或分位哑变量。Freyberger–Neuhierl–Weber 的非参数结果表明许多特征的效应集中在尾部，这与「只用 rank 再线性」并不矛盾：rank 已经把尾部标出来。</p><p>滞后机制是可交易性。市场只对信息集 \\(\\mathcal{F}_t\\) 定价。特征若属于 \\(\\mathcal{F}_{t+k}\\)，回归估的是不可实施的相关。McLean 与 Pontiff（2016）的发表后衰减之外，还有一类更平凡的衰减：研究用了比实盘更短的滞后。</p><h3 id="高维特征中的共线与-rank-的限度" tabindex="-1">高维特征中的共线与 rank 的限度 <a class="header-anchor" href="#高维特征中的共线与-rank-的限度" aria-label="Permalink to &quot;高维特征中的共线与 rank 的限度&quot;">​</a></h3><p>几十个特征在截面上高度相关（价值族、质量族）。逐列 rank 不消除共线，只统一量纲。随后仍需正交、PCA、IPCA 或正则，见<a href="/quant/cov-shrinkage">协方差收缩</a>与 Kozak–Nagel–Santosh。GBDT 会把共线列的重要性拆得看起来很散，或集中在某一列上随种子变化。报告时应给一族特征的联合置换重要性，而不是只看单列 gain。Green–Hand–Zhang 的问题意识仍适用：独立信息含量，不是列数。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用未来宇宙（事后进入指数的成分）做当日 rank。不要把测试期的截面均值与标准差用于训练期标准化。不要对百分比特征再做一次跨期标准化导致双重缩放。中文会计科目与海外 Compustat 的滞后规则不同，必须按交易所披露时钟重写，而不是翻译列名。另类数据列的滞后往往长于供应商宣传的「T+1」，应以你实际收到文件的时间为准。</p><p>Rank 在 \\(N_t\\) 很小时（行业内三只股票）不稳定。应设最小截面宽度，否则分位在 0、0.5、1 上跳动，成为噪声源。</p><p><span class="marginnote">特征存储应保存原始值、滞后后的可交易值、以及 rank 后的值三层，并记录 \\(U_t\\) 名单。只存最终分位，五年后无法回答「当时宇宙里有没有这只停牌股」。</span></p>',26)),(e(),l(d,null,{default:n(()=>[u(t,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E5%8E%9F%E5%A7%8B%E6%8F%8F%E8%BF%B0%E5%AD%90%22%5D%20--%3E%20LAG%5B%22%E6%8C%89%E5%88%97%3A%20%E5%85%AC%E5%91%8A%E6%97%A5%20%2F%20vintage%20%2F%20%E7%BC%93%E5%86%B2%22%5D%0A%20%20LAG%20--%3E%20U%5B%22%E5%8F%AF%E6%8A%95%E8%B5%84%E5%AE%87%E5%AE%99%20U_t%22%5D%0A%20%20U%20--%3E%20RK%5B%22%E6%88%AA%E9%9D%A2%20rank%20%E6%88%96%E8%A1%8C%E4%B8%9A%E5%86%85%E5%88%86%E4%BD%8D%22%5D%0A%20%20RK%20--%3E%20ORTH%5B%22%E5%8F%AF%E9%80%89%3A%20%E8%A1%8C%E4%B8%9A%E5%B8%82%E5%80%BC%E6%AD%A3%E4%BA%A4%22%5D%0A%20%20ORTH%20--%3E%20MOD%5B%22%E7%BA%BF%E6%80%A7%E6%88%96%20GBDT%22%5D%0A%20%20LAG%20--%3E%20AUDIT%5B%22%E4%BF%A1%E6%81%AF%E9%9B%86%20F_t%20%E5%AE%A1%E8%AE%A1%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>滞后定义信息集：Fama–French 的会计滞后与 Hou–Xue–Zhang 的复制纪律，比模型选择更常决定异常是否存在。</li><li>截面 rank 统一量纲、压制极端值、去掉水平漂移；宇宙与行业内总体必须与可交易集合一致。</li><li>按列滞后、按日 rank；用最慢列统一延迟会浪费高频信息，用未公布会计会前视。</li><li>Rank 不消除特征族共线；增量信息仍要按 Green–Hand–Zhang 与 IPCA / 收缩的逻辑检验。</li><li>出处：Fama and French, <em>Journal of Finance</em> / <em>JFE</em> 对 HML 的构造；Hou, Xue and Zhang, <em>RFS</em>, 2020；Green, Hand and Zhang, <em>RFS</em>, 2017；Kelly, Pruitt and Su, <em>JF</em>, 2019；Kozak, Nagel and Santosh, <em>JF</em>, 2020；Freyberger, Neuhierl and Weber, <em>RFS</em>, 2020；Gu, Kelly and Xiu, <em>RFS</em>, 2020。</li></ul>',2))])}const f=o(p,[["render",k]]);export{F as __pageData,f as default};
